"""Candidate accelerated XY relaxation with exactly pinned physical boundaries.

The matrix is the degree-normalized graph Laplacian on free mesh vertices.
Its eigenvalues lie in (0, 2] when every component has a fixed vertex. A
Chebyshev recurrence accelerates the existing neighbor-mean iteration; it does
not move boundaries or change connectivity. The lower spectral estimate sets
convergence speed, not a geometric validity guarantee. Final surface guards
remain required, and the residual is exposed for independent qualification.
"""
import bpy

NAME='Street Blosm / Accelerated pinned relaxation v1'


def build():
    existing=bpy.data.node_groups.get(NAME)
    if existing:return existing
    from ..kernel.backend_runtime import Graph, V, rm, named, choose, remove, repeat
    from ..kernel.backend_relax import arm_masks
    from ..kernel import prepare

    g=Graph(NAME)
    for key in ('Geometry','Arms'):g.socket(key,'NodeSocketGeometry')
    g.socket('Grid Intervals','NodeSocketInt',default=64)
    g.socket('Iterations','NodeSocketInt',default=0)
    g.socket('Geometry','NodeSocketGeometry','OUTPUT')
    g.socket('Residual','NodeSocketFloat','OUTPUT')
    inp=g.node('NodeGroupInput');arms=inp.outputs['Arms']
    geo=g.store(inp.outputs['Geometry'],'initial_xy',g.position(),'POINT','FLOAT_VECTOR')
    geo=g.store(geo,'fixed_xy',g.math('MAXIMUM',named(g,'outer_boundary','BOOLEAN'),
                                    named(g,'plateau_boundary','BOOLEAN')),'POINT','BOOLEAN')
    start,end=repeat(g,geo,rm.count(g,arms),'Keep original complete approach profiles fixed')
    street,_,_=arm_masks(g,arms,V(g,start.outputs['Iteration']))
    step=g.store(start.outputs['Geometry'],'fixed_xy',
                 g.math('MAXIMUM',street,named(g,'fixed_xy','BOOLEAN')),'POINT','BOOLEAN')
    g.bind(step,end.inputs['Geometry'])
    geo=g.store(end.outputs['Geometry'],'_cheb_previous',g.position(),'POINT','FLOAT_VECTOR')

    intervals=g.math('MAXIMUM',4.,V(g,inp.outputs['Grid Intervals']))
    lower=g.math('DIVIDE',2.,intervals*intervals)
    d=(2.+lower)*.5;c=(2.-lower)*.5;sigma=d/c
    iterations=choose(g,g.math('GREATER_THAN',V(g,inp.outputs['Iterations']),0.),
                      inp.outputs['Iterations'],4.*intervals,'INT')
    start,end=repeat(g,geo,iterations,'Accelerated free-vertex relaxation')
    end.repeat_items.new('FLOAT','Rho')
    g.bind(g.math('DIVIDE',1.,sigma),start.inputs['Rho'])
    at=V(g,start.outputs['Iteration']);rho=V(g,start.outputs['Rho'])
    first=rm.equal(g,at,0)
    next_rho=choose(g,first,g.math('DIVIDE',1.,sigma),g.math('DIVIDE',1.,2.*sigma-rho))
    alpha=choose(g,first,g.math('DIVIDE',1.,d),2.*next_rho/c)
    beta=choose(g,first,0.,rho*next_rho)
    position=g.position();xyz=g.separate(position)
    previous=g.separate(named(g,'_cheb_previous','FLOAT_VECTOR'))
    blur=g.node('GeometryNodeBlurAttribute','Self and edge-neighbor mean');blur.data_type='FLOAT_VECTOR'
    blur.inputs['Iterations'].default_value=1;g.bind(position,blur.inputs['Value'])
    mean=g.separate(V(g,blur.outputs['Value']))
    degree=g.math('MAXIMUM',V(g,g.node('GeometryNodeInputMeshVertexNeighbors').outputs['Vertex Count']),1.)
    residual=[(degree+1.)*(m-p)/degree for m,p in zip(mean,xyz)]
    candidate=[p+alpha*r+beta*(p-old) for p,r,old in zip(xyz,residual,previous)]
    # Capture the proposal before replacing the previous iterate. Otherwise
    # deferred fields would read the new value and lose their momentum term.
    step=g.store(start.outputs['Geometry'],'_cheb_candidate',g.xyz(*candidate),'POINT','FLOAT_VECTOR')
    step=g.store(step,'_cheb_previous',position,'POINT','FLOAT_VECTOR')
    move=g.node('GeometryNodeSetPosition','Move only free interior vertices')
    g.bind(step,move.inputs['Geometry']);g.bind(1.-named(g,'fixed_xy','BOOLEAN'),move.inputs['Selection'])
    g.bind(named(g,'_cheb_candidate','FLOAT_VECTOR'),move.inputs['Position'])
    g.bind(move.outputs['Geometry'],end.inputs['Geometry']);g.bind(next_rho,end.inputs['Rho'])
    final=end.outputs['Geometry']
    error=g.math('SQRT',sum(v*v for v in residual))*(1.-named(g,'fixed_xy','BOOLEAN'))
    maximum=prepare.stat(g,final,error)
    final=g.store(final,'_relax_residual',maximum,'POINT','FLOAT')
    final=g.store(final,'_relax_iterations',iterations,'POINT','INT')
    for key in ('_cheb_candidate','_cheb_previous'):final=remove(g,final,key)
    out=g.node('NodeGroupOutput');g.bind(final,out.inputs['Geometry']);g.bind(maximum,out.inputs['Residual'])
    g.g['construction']='Degree-normalized Chebyshev relaxation; exact boundary/profile pins; no runtime Python'
    g.g['scope']='Candidate for half-profile junctions; final mesh and profile checks remain mandatory'
    return g.g
